class Solution {
public:
    int rob(vector<int>& nums) {
        int n=nums.size();
        vector<int> dp(n+1);
        dp[0]=0,dp[1]=nums[0];
        for(int i=1;i<n;i++)
        {
            int val=nums[i];
            dp[i+1]=max(dp[i],dp[i-1]+val);
        }
        return dp[n];
    }
};
